use crate::{editor::{Editor,Action},camera::Projection,scene::Scene};
use session_rust::{Geometry,Point,Vector,Xform,Line,Polyline,Mesh,PointCloud};
use std::rc::Rc;
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(action)=e.tool_line(line){action.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(action)=crate::commands::parse(line)?else{return Err("Editor command".into())};action};e.apply(action).map_err(str::to_owned)?;Ok(())}
fn history(e:&Editor)->usize{e.scenes().count()}
#[test]
fn named_views_and_view_grid_use_the_current_drawing_plane(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();let source=e.scene.lines()[0].prepared.source.clone();let n=history(&e);
    for(view,plane)in[("Top",crate::cplane::CPlane::Xy),("Front",crate::cplane::CPlane::Xz),("Right",crate::cplane::CPlane::Yz),("Isometric",crate::cplane::CPlane::Xy),("Isometric Back",crate::cplane::CPlane::Xy)]{
        command(&mut e,"Construction Plane View").unwrap();command(&mut e,&format!("View {view}")).unwrap();assert_eq!(e.camera.projection,Projection::Orthographic);assert_eq!(e.drawing_plane(),plane);
        for line in crate::grid::Settings::default().strokes_on(plane).unwrap().iter().take(22){for p in [line.start,line.end]{let local=plane.local(&Point::new(p[0]as f64,p[1]as f64,p[2]as f64));assert!(local[2].abs()<1e-8);}}
    }
    command(&mut e,"CPlane XZ").unwrap();command(&mut e,"View Top").unwrap();assert_eq!(e.drawing_plane(),crate::cplane::CPlane::Xz);assert_eq!(e.camera.grid_plane,Some(crate::cplane::CPlane::Xz));assert_eq!(history(&e),n);assert!(Rc::ptr_eq(&source,&e.scene.lines()[0].prepared.source));
    command(&mut e,"Curve w0,0,0").unwrap();command(&mut e,"View Front").unwrap();assert_eq!(e.draft.as_ref().unwrap().points,vec![[0.;3]]);command(&mut e,"Escape").unwrap();assert!(e.draft.is_none());
    assert!(crate::commands::parse(&"x".repeat(65537)).is_err());for name in ["object","FACE","edge","esc"]{assert!(crate::commands::parse(name).is_ok());}
}
#[test]
fn queries_preserve_selection_on_misses_and_exclude_hidden_locked_rows(){
    let mut e=editor();let mut small=Line::new(0.,0.,0.,3.,4.,0.);small.name="Träger A1".into();let id=e.scene.insert_line(crate::stroke::PreparedLine::new(Rc::new(small)).unwrap()).unwrap();let mut big=Line::new(0.,0.,0.,20.,0.,0.);big.name="Beam B2".into();let other=e.scene.insert_line(crate::stroke::PreparedLine::new(Rc::new(big)).unwrap()).unwrap();
    command(&mut e,"Select By Name \"TRÄGER\"").unwrap();assert_eq!(e.selected_objects(),vec![id]);assert!(command(&mut e,"Select Small 5").is_err());assert_eq!(e.selected_objects(),vec![id]);command(&mut e,"selectsmall 5.1").unwrap();assert_eq!(e.selected_objects(),vec![id]);
    Rc::make_mut(&mut e.scene.view).lock(&[other],true);assert!(command(&mut e,"Select By Name beam").is_err());Rc::make_mut(&mut e.scene.view).hide(&[id],true);assert!(command(&mut e,"Select Small 100").is_err());
    for line in ["Select By Name","Select By Name \"\"","Select Small 0","Select Small NaN","Select Small 1 2"]{assert!(command(&mut e,line).is_err());}
}
#[test]
fn arrow_heads_keep_source_identity_and_undo_as_one_change(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w3,0,0").unwrap();let id=e.scene.lines()[0].id;let source=e.scene.lines()[0].prepared.source.clone();let guid=e.scene.row_guid(id).unwrap().to_owned();e.select_objects([id],false);command(&mut e,"Arrowhead Both").unwrap();assert_eq!(e.scene.paths().len(),1);let Geometry::Line(next)=crate::source_edit::original(&e.scene,id).unwrap()else{panic!()};assert_eq!(next.arrowhead,session_rust::Arrowhead::BOTH);assert_eq!(e.scene.row_guid(id),Some(guid.as_str()));assert_eq!(e.scene.paths()[0].prepared.heads,3);assert_eq!(source.arrowhead,session_rust::Arrowhead::NONE);
    command(&mut e,"Undo").unwrap();assert_eq!(e.scene.lines().len(),1);assert!(Rc::ptr_eq(&source,&e.scene.lines()[0].prepared.source));command(&mut e,"Redo").unwrap();assert_eq!(e.scene.paths()[0].prepared.heads,3);let n=history(&e);command(&mut e,"Arrowhead Both").unwrap();assert_eq!(history(&e),n);
    command(&mut e,"Arrow w0,1,0 w2,1,0").unwrap();assert_eq!(e.scene.paths().last().unwrap().prepared.heads,1);let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut opened=Scene::empty();crate::scene_document::open(&mut opened,&bytes).unwrap();assert_eq!(opened.paths().iter().map(|r|r.prepared.heads).collect::<Vec<_>>(),vec![3,1]);
}
#[test]
fn explode_keeps_parent_placement_and_originals_then_restores_all_pieces(){
    let mut e=editor();let source=Rc::new(Polyline::new(vec![Point::new(0.,0.,0.),Point::new(1.,0.,0.),Point::new(1.,1.,0.)]));let id=e.scene.insert_path(crate::chain::PreparedChain::polyline(source.clone()).unwrap()).unwrap();e.scene.place_following(id,Xform::translation(10.,20.,30.)).unwrap();e.select_objects([id],false);command(&mut e,"Explode").unwrap();assert_eq!(e.scene.paths().len(),2);assert!(!e.scene.contains(id));for row in e.scene.paths(){assert!(matches!(row.prepared.source,crate::chain::Source::Line(_)));assert_eq!(row.model.m[12..15],[10.,20.,30.]);}assert_eq!(e.selected_objects().len(),2);
    command(&mut e,"Undo").unwrap();assert_eq!(e.scene.paths().len(),1);let Geometry::Polyline(restored)=crate::source_edit::original(&e.scene,id).unwrap()else{panic!()};assert!(Rc::ptr_eq(&source,&restored));command(&mut e,"Redo").unwrap();assert_eq!(e.scene.paths().len(),2);
    let mut cloud=PointCloud::new(vec![Point::new(2.,3.,4.),Point::new(5.,6.,7.)],vec![Vector::z_axis();2],vec![session_rust::Color::red();2]);cloud.name="scan".into();let cloud=Rc::new(cloud);let id=e.scene.insert_cloud(crate::cloud::Prepared::new(cloud.clone()).unwrap()).unwrap();e.select_objects([id],false);command(&mut e,"Explode").unwrap();assert!(e.scene.clouds().is_empty());assert_eq!(e.scene.points().len(),2);assert_eq!(e.scene.points()[1].prepared.source[0],5.);command(&mut e,"Undo").unwrap();assert!(Rc::ptr_eq(&cloud,&e.scene.clouds()[0].prepared.source));
}
#[test]
fn original_text_accepts_height_on_a_fixed_plane_and_keeps_invalid_input(){
    let mut e=editor();command(&mut e,"CPlane XZ").unwrap();command(&mut e,"View Front").unwrap();command(&mut e,"Text Hello world").unwrap();command(&mut e,"Height").unwrap();assert!(command(&mut e,"0").is_err());assert!(e.draft.as_ref().unwrap().text.as_ref().unwrap().asking);command(&mut e,"2").unwrap();command(&mut e,"1,3").unwrap();assert!(e.draft.is_none());assert_eq!(e.scene.texts().len(),1);let source=e.scene.texts()[0].prepared.source.clone();assert_eq!(source.label.text,"Hello world");let crate::text::TextPlacement::WorldPlane{world,right,up,world_height}=source.label.placement else{panic!()};assert_eq!(right,[1.,0.,0.]);assert_eq!(up,[0.,0.,1.]);assert!((world[2]-(3.+2.*26./18.)).abs()<1e-12);assert_eq!(world_height,2.);assert_eq!(e.last_text_height,2.);
    command(&mut e,"Undo").unwrap();assert!(e.scene.texts().is_empty());command(&mut e,"Redo").unwrap();assert!(Rc::ptr_eq(&source,&e.scene.texts()[0].prepared.source));let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut opened=Scene::empty();crate::scene_document::open(&mut opened,&bytes).unwrap();assert_eq!(opened.texts()[0].prepared.source.label.text,"Hello world");
    command(&mut e,"Curve w0,0,0").unwrap();assert!(command(&mut e,&format!("Text {}","é".repeat(81))).is_err());assert_eq!(e.draft.as_ref().unwrap().points,vec![[0.;3]]);command(&mut e,"Escape").unwrap();command(&mut e,"Text é").unwrap();assert_eq!(e.draft.as_ref().unwrap().text.as_ref().unwrap().height,2.);command(&mut e,"Escape").unwrap();assert!(e.draft.is_none());
}
fn trim_scene()->(Editor,crate::scene::ObjectId,crate::scene::ObjectId){let mut e=editor();command(&mut e,"Line w-2,0,0 w2,0,0").unwrap();command(&mut e,"Line w0,-2,0 w0,2,0").unwrap();let ids=e.scene.lines().iter().map(|r|r.id).collect::<Vec<_>>();command(&mut e,"View Top").unwrap();command(&mut e,"Select None").unwrap();command(&mut e,"Fit").unwrap();(e,ids[0],ids[1])}
#[test]
fn trim_world_hit_commits_once_and_retains_the_original_cutter(){
    let(mut e,target,cutter)=trim_scene();let original=e.scene.lines()[0].prepared.source.clone();e.select_objects([target],false);command(&mut e,"Trim").unwrap();assert!(e.gizmo_origin().is_none());assert_eq!(e.trim.as_ref().unwrap().phase,crate::trim_draft::Phase::Cutters);e.apply(Action::TrimPick(Some(cutter))).unwrap();command(&mut e,"Trim").unwrap();assert_eq!(e.trim.as_ref().unwrap().cuts[0].parts.count(),2);
    let p=e.camera.view_projection().m;let q=[p[0]*-1.+p[12],p[1]*-1.+p[13],p[3]*-1.+p[15]];let screen=[(q[0]/q[2])as f32,(q[1]/q[2])as f32];e.apply(Action::TrimScreen{screen,size:[640.,480.],commit:true}).unwrap();assert!(e.trim.is_none());let Geometry::Line(next)=crate::source_edit::original(&e.scene,target).unwrap()else{panic!()};assert!(next.start()[0].abs()<1e-8);assert_eq!(next.end()[0],2.);assert_eq!(original.start()[0],-2.);assert_eq!(e.scene.lines()[1].id,cutter);
    command(&mut e,"Undo").unwrap();assert!(Rc::ptr_eq(&original,&e.scene.lines()[0].prepared.source));command(&mut e,"Redo").unwrap();assert_eq!(e.scene.lines()[0].prepared.source.start()[0],0.);
}
#[test]
fn trim_toggles_empty_confirmation_and_escape_preserve_sources_and_redo(){
    let(mut e,target,cutter)=trim_scene();command(&mut e,"Example Box").unwrap();command(&mut e,"Undo").unwrap();let original=e.scene.lines()[0].prepared.source.clone();e.select_objects([target],false);command(&mut e,"Trim").unwrap();assert!(command(&mut e,"Trim").is_err());e.apply(Action::TrimPick(Some(cutter))).unwrap();e.apply(Action::TrimPick(Some(cutter))).unwrap();assert!(e.trim.as_ref().unwrap().cutters.is_empty());e.apply(Action::TreePick{ids:vec![cutter],additive:false}).unwrap();command(&mut e,"Trim").unwrap();command(&mut e,"View Front").unwrap();assert!(e.trimming_parts());command(&mut e,"Escape").unwrap();assert_eq!(e.selected_objects(),vec![target]);assert!(Rc::ptr_eq(&original,&e.scene.lines()[0].prepared.source));command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects().len(),1);
    e.select_objects([target],false);command(&mut e,"Trim 0.25 0.75").unwrap();assert_eq!(e.scene.lines()[0].prepared.source.start()[0],-1.);assert_eq!(e.scene.lines()[0].prepared.source.end()[0],1.);command(&mut e,"Undo").unwrap();assert!(Rc::ptr_eq(&original,&e.scene.lines()[0].prepared.source));
}
#[test]
fn actual_guides_cache_css_dashes_labels_and_grid_without_pick_ownership(){
    let scene=Scene::empty();let instance=wgpu::Instance::new(wgpu::InstanceDescriptor{backends:wgpu::Backends::VULKAN,flags:Default::default(),memory_budget_thresholds:Default::default(),backend_options:Default::default(),display:None});let adapter=pollster::block_on(instance.request_adapter(&Default::default())).unwrap();let(device,queue)=pollster::block_on(adapter.request_device(&Default::default())).unwrap();let mut renderer=crate::renderer::Renderer::new(device,queue,wgpu::TextureFormat::Rgba8Unorm,&scene);renderer.resize(crate::viewport::Viewport{width:320,height:240});
    let mut overlay=crate::guide_gpu::Overlay::default();overlay.wire(&[[-0.8,-0.3,0.2],[0.8,-0.3,0.2]],[210./255.,40./255.,40./255.,1.],true);overlay.wire(&[[-0.8,0.3,0.2],[0.8,0.3,0.2]],[30./255.,110./255.,170./255.,1.],false);overlay.label=Some(([0.,0.,0.2],"remove".into()));renderer.set_guides(&overlay).unwrap();let bytes=renderer.guide_bytes();let shaping=renderer.text_usage()[0];renderer.set_guides(&overlay).unwrap();assert_eq!(renderer.guide_bytes(),bytes);assert_eq!(renderer.text_usage()[0],shaping);assert!(bytes>0);
    renderer.set_grid_on(Some(crate::grid::Settings::default()),crate::cplane::CPlane::Xz).unwrap();let uploads=renderer.grid_usage();renderer.set_grid_on(Some(crate::grid::Settings::default()),crate::cplane::CPlane::Xz).unwrap();assert_eq!(renderer.grid_usage(),uploads);renderer.set_grid_on(None,crate::cplane::CPlane::Xz).unwrap();
    let texture=renderer.device.create_texture(&wgpu::TextureDescriptor{label:None,size:wgpu::Extent3d{width:320,height:240,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});let view=texture.create_view(&Default::default());let matrix=Xform::identity().m.map(|v|v as f32);renderer.draw(&view,&crate::background::Background::default(),&matrix);
    let buffer=renderer.device.create_buffer(&wgpu::BufferDescriptor{label:None,size:1280*240,usage:wgpu::BufferUsages::COPY_DST|wgpu::BufferUsages::MAP_READ,mapped_at_creation:false});let mut encoder=renderer.device.create_command_encoder(&Default::default());encoder.copy_texture_to_buffer(wgpu::TexelCopyTextureInfo{texture:&texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},wgpu::TexelCopyBufferInfo{buffer:&buffer,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(1280),rows_per_image:Some(240)}},texture.size());renderer.queue.submit([encoder.finish()]);let(tx,rx)=std::sync::mpsc::channel();buffer.slice(..).map_async(wgpu::MapMode::Read,move|result|tx.send(result).unwrap());renderer.device.poll(wgpu::PollType::Wait{submission_index:None,timeout:Some(std::time::Duration::from_secs(5))}).unwrap();rx.recv().unwrap().unwrap();let pixels=buffer.slice(..).get_mapped_range();let red=pixels.chunks_exact(4).filter(|p|p[0]>150&&p[1]<100&&p[2]<100).count();let blue=pixels.chunks_exact(4).filter(|p|p[0]<100&&p[1]>70&&p[2]>120).count();assert!(red>100&&blue>100,"actual red dashed and blue solid guides: {red}, {blue}");assert!(red<blue,"dashes leave real gaps at the same CSS width");drop(pixels);buffer.unmap();
    renderer.request_pick([0.,-0.3],matrix).unwrap();renderer.device.poll(wgpu::PollType::Wait{submission_index:None,timeout:Some(std::time::Duration::from_secs(5))}).unwrap();assert_eq!(renderer.take_pick(matrix).unwrap().unwrap(),None);assert!(scene.all_ids().is_empty());renderer.set_guides(&Default::default()).unwrap();assert_eq!(renderer.guide_bytes(),0);assert_eq!(renderer.text_usage()[0],0);
}
